chain = () => {
  let el = document.querySelector('.vw-app');
  if (!el) throw new Error('.vw-app not found — the page failed to load or auth failed');
  const out = [];
  while (el && out.length < 9) {
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    out.push({
      tag: el.tagName.toLowerCase(),
      // SVG elements expose className as an SVGAnimatedString, so read the attribute.
      cls: String(el.getAttribute('class') || el.id || '').slice(0, 34),
      h: +r.height.toFixed(1),
      cssH: cs.height,
      display: cs.display,
      flex: cs.flex,
      minH: cs.minHeight,
      overflow: cs.overflow,
    });
    el = el.parentElement;
  }
  return out;
}

.hermes/probe_heights.js::chain.source_code:
chain = () => {
  const svg = document.querySelector('svg[data-vw="canvas"]');
  const out = [];
  let el = svg;
  while (el && el !== document.documentElement) {
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    out.push({
      // The slice applies to the whole selector, not just the class suffix.
      sel: (el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') +
        (el.className && typeof el.className === 'string'
          ? '.' + el.className.trim().split(/\s+/).join('.')
          : '')).slice(0, 40),
      height: +r.height.toFixed(1),
      display: cs.display,
      flex: cs.flex,
      minHeight: cs.minHeight,
      overflow: cs.overflowY,
    });
    el = el.parentElement;
  }
  return out;
}

