dashboard/dist/index.js::edgePath.source_code:
function edgePath(parent, child) {
    var p = outPort(parent);
    var q = inPort(child);
    var bend = Math.max(30, Math.abs(q.x - p.x) / 2);
    return "M" + p.x + "," + p.y +
      "C" + (p.x + bend) + "," + p.y + " " + (q.x - bend) + "," + q.y + " " + q.x + "," + q.y;
  }

dashboard/dist/index.js::explain.source_code:
function explain(err) {
    var text = err && err.message ? err.message : String(err);
    var i = text.indexOf(": ");
    if (i > 0 && /^\d{3}$/.test(text.slice(0, i))) {
      var body = text.slice(i + 2);
      try {
        var parsed = JSON.parse(body);
        if (parsed && parsed.detail) {
          return typeof parsed.detail === "string" ? parsed.detail : JSON.stringify(parsed.detail);
        }
      } catch (ignored) {
        /* not JSON: show the body as-is */
      }
      return body;
    }
    return text;
  }

