function deliveryLine(result) {
    const list = result.deliveries || [];
    if (!list.length) return null;
    return line("p", "delivery: " + list.map((d) => {
      return (d.ok ? "sent " : "FAILED ") + d.node_id + " \u2192 " + (d.target || "?") +
        (d.detail ? " " + d.detail : "");
    }).join(" \u00b7 "), "vw-muted");
