def send_text(target: str, text: str) -> dict:
    """Send *text* to *target* via the host seam. Never raises."""
    try:
        from tools.send_message_tool import send_message_tool
    except Exception as exc:  # host not importable (tests, standalone tooling)
        return {"target": target, "ok": False, "detail": f"host send seam unavailable: {exc}"}
    try:
        raw = send_message_tool({"action": "send", "target": target, "message": text})
    except Exception as exc:  # the seam catches its own errors; this is a last resort
        return {"target": target, "ok": False, "detail": f"send failed: {exc}"}
    if isinstance(raw, dict):
        data = raw
    else:
        try:
            data = json.loads(raw or "{}")
        except (ValueError, TypeError):
            # A plain-text error from the seam is the only diagnosis available; keep it
            # instead of reducing the receipt to a generic "send failed".
            data = {"error": raw} if raw else {}
    if isinstance(data, dict) and data.get("success"):
        return {"target": target, "ok": True, "detail": str(data.get("note") or "sent")}
    detail = (data or {}).get("error") if isinstance(data, dict) else raw
    return {"target": target, "ok": False, "detail": str(detail or "send failed")}

visual_workflow_hermes/delivery.py::deli.source_code:
def deliver_output(step: dict, payload, run_name: str = "") -> dict:
    """Deliver one output node's payload. Returns ``{target, ok, detail}``; never raises.

    Called by the runner for every output step that declares a ``deliver`` mode; a node that
    only collects has no mode and is not passed here.
    """
    mode = str(step.get("deliver") or "").strip().lower()
    if mode not in MODES:
        return dict(_COLLECT_ONLY)
    target = str(step.get("target") or "").strip()
    if not target:
        return {"target": "", "ok": False, "detail": "output node has no target"}
    if mode == "channel" and ":" not in target:
        return {
            "target": target,
            "ok": False,
            "detail": "a channel target needs <platform>:<chat id>",
        }
    text = render_text(run_name, str(step.get("id") or ""), payload)
    return send_text(target, text)

visual_workflow_hermes/models.py::list_h.source_code:
def list_host_models(refresh: bool = False) -> dict:
    """``{"providers": [{slug, label, models}], "available": bool, "current": {model, provider}}``.

    ``available`` is False when the host catalog could not be read (or every provider was
    unusable), which is the canvas' cue to fall back to free-text.
    """
    global _cache
    # The cache is shared process-wide: hand every caller its own copy, or one route that
    # mutates the payload poisons the catalog for everyone until the TTL expires.
    if not refresh and _cache is not None and time.monotonic() - _cache[0] < _CACHE_TTL_S:
        return copy.deepcopy(_cache[1])
    payload = _read_catalog()
    _cache = (time.monotonic(), payload)
    return copy.deepcopy(payload)

visual_workflow_hermes/models.py::_read_.source_code:
def _read_catalog() -> dict:
    try:
        from hermes_cli.inventory import build_model_options_payload, load_picker_context

        raw = build_model_options_payload(load_picker_context())
    except Exception:  # host not importable, or its catalog build failed
        return {"providers": [], "available": False, "current": {}}
    if not isinstance(raw, dict):
        return {"providers": [], "available": False, "current": {}}

    providers: list[dict] = []
    for row in raw.get("providers") or []:
        if not isinstance(row, dict):
            continue
        slug = str(row.get("slug") or "").strip()
        models: list[str] = []
        for entry in row.get("models") or []:
            # The host hands plain id strings today; accept a dict entry too so a payload
            # change degrades to "no models" instead of a 500.
            model_id = entry.get("id") if isinstance(entry, dict) else entry
            model_id = str(model_id or "").strip()
            if model_id and model_id not in models:
                models.append(model_id)
        if not slug or not models:
            continue
        providers.append(
            {
                "slug": slug,
                "label": str(row.get("name") or row.get("label") or slug),
                "models": models,
            }
        )
    return {
        "providers": providers,
        "available": bool(providers),
        "current": {
            "model": str(raw.get("model") or ""),
            "provider": str(raw.get("provider") or ""),
        },
    }

visual_workflow_hermes/models.py::provid.source_code:
def provider_for_model(model: str, catalog: Optional[dict] = None) -> str:
    """Provider slug that serves *model*, or "" when it cannot be known.

    A model id is usually provider-prefixed (``anthropic/claude-…``) so the answer is
    unambiguous; when the same id is listed by several providers the host's current provider
    wins, and an unclear case returns "" so the host's own default routing stays in charge
    instead of guessing wrong.
    """
    wanted = (model or "").strip()
    if not wanted:
        return ""
    payload = catalog if catalog is not None else list_host_models()
    current = payload.get("current") or {}
    hits = [
        str(p.get("slug") or "")
        for p in payload.get("providers") or []
        if wanted in (p.get("models") or [])
    ]
    hits = [slug for slug in hits if slug]
    if not hits:
        return ""
    if len(hits) == 1:
        return hits[0]
    if current.get("model") == wanted and current.get("provider") in hits:
        return str(current["provider"])
    return ""

