def tool_save(self, args, **_) -> dict:
    name = args.get("name") or ""
    graph = args.get("graph")
    if not isinstance(graph, dict):
        return {"ok": False, "error": "graph must be an object"}
    try:
        path = self._store().save(name, graph)
    except (ValueError, OSError) as exc:
        # Bad name or invalid graph: report it, never raise into the tool dispatcher.
        return {"ok": False, "error": str(exc)}
    return {"ok": True, "path": str(path), "nodes": len(graph.get("nodes", []))}

def tool_load(self, args, **_) -> dict:
    name = args.get("name") or ""
    try:
        return {"ok": True, "graph": self._store().load(name)}
    except (FileNotFoundError, ValueError) as exc:
        return {"ok": False, "error": str(exc)}

def tool_validate(self, args, **_) -> dict:
    from .schema import validate_designer_graph

    graph = args.get("graph")
    if not isinstance(graph, dict):
        return {"ok": False, "error": "graph must be an object"}
    errors = validate_designer_graph(graph)
    return {"ok": not errors, "errors": errors}

def tool_run(self, args, **_) -> dict:
    """Start a run: validate, build the plan, execute until done or paused.

    With ``retry: <run_id>`` instead of ``name`` it re-runs a failed run from the step
    it failed on — the same runner reset a canvas Retry button goes through.
    """
    retry_id = str(args.get("retry") or "").strip()
    if retry_id:
        return self._tool_run_retry(retry_id)
    from .convert import build_run_plan
    from .runner import StepError, new_state, run_plan
    from .schema import validate_designer_graph

    name = args.get("name") or ""
    try:
        designer = self._store().load(name)
    except (FileNotFoundError, ValueError) as exc:
        return {"ok": False, "error": str(exc)}
    errors = validate_designer_graph(designer)
    if errors:
        return {"ok": False, "errors": errors}
    # The tool contract is a plain dict, never a raise into the dispatcher: plan
    # building, the first save, and a corrupt-state KeyError all stay here.
    try:
        plan = build_run_plan(designer)
        run_id = uuid.uuid4().hex[:12]
        state = new_state(plan, run_id)
        runs = self._runs()
        runs.save(state)
        state = run_plan(plan, state, spawn=_subagent_spawn(self.ctx),
                         on_step=runs.save, deliver=_deliver)
    except (StepError, ValueError, TypeError, FileNotFoundError, OSError, KeyError) as exc:
        return {"ok": False, "error": str(exc)}
    return self._result(state)

def _tool_run_retry(self, run_id: str) -> dict:
    """Re-run a failed run from its failed step (``workflow_design_run retry=<id>``).

    All guards sit here (not only in the runner) so the tool reports every refusal as a
    result the dispatcher can print, never a raise into the tool dispatcher.
    """
    from .convert import build_run_plan
    from .runner import StepError, retry_failed, retryable

    try:
        state = self._runs().load(run_id)
    except (FileNotFoundError, ValueError) as exc:
        return {"ok": False, "error": str(exc)}
    if not retryable(state):
        return {
            "ok": False,
            "error": f"run {run_id!r} is {state.get('status')!r}, "
                     "not failed — nothing to retry",
        }
    name = state.get("name")
    if not isinstance(name, str) or not name:
        return {"ok": False,
                "error": f"run {run_id!r} record is corrupt: missing 'name'"}
    try:
        plan = build_run_plan(self._store().load(name))
        state = retry_failed(plan, state, spawn=_subagent_spawn(self.ctx),
                             on_step=self._runs().save, deliver=_deliver)
    except (StepError, ValueError, TypeError, FileNotFoundError, OSError, KeyError) as exc:
        return {"ok": False, "error": str(exc)}
    return self._result(state)

def tool_respond(self, args, **_) -> dict:
    """Resume a paused run with an approval answer or a pending agent output."""
    from .convert import build_run_plan
    from .runner import StepError, resume_plan

    run_id = args.get("run_id") or ""
    node_id = args.get("node_id") or ""
    # A structured agent result wins over the plain string; either can be fed back.
    answer = args.get("structured")
    if answer is None:
        answer = args.get("answer")
    try:
        state = self._runs().load(run_id)
    except (FileNotFoundError, ValueError) as exc:
        return {"ok": False, "error": str(exc)}
    pending = state.get("pending") or {}
    if not isinstance(pending, dict):
        return {"ok": False,
                "error": f"run {run_id!r} record is corrupt: pending is not an object"}
    if pending.get("node_id") != node_id:
        return {"ok": False,
                "error": f"run {run_id!r} is not waiting on {node_id!r}"}
    name = state.get("name")
    if not isinstance(name, str) or not name:
        return {"ok": False,
                "error": f"run {run_id!r} record is corrupt: missing 'name'"}
    try:
        plan = build_run_plan(self._store().load(name))
        state = resume_plan(plan, state, answer, spawn=_subagent_spawn(self.ctx),
                            on_step=self._runs().save, deliver=_deliver)
    except (StepError, ValueError, TypeError, FileNotFoundError, OSError, KeyError) as exc:
        return {"ok": False, "error": str(exc)}
    return self._result(state)

